/**
 * 输入框右端「文件」按钮（conversation.input.right 槽）。
 *
 * 与 meow-dsh-task 的「任务」按钮同款：加性列表条目注册进空置槽（发送键前、工具行右端）。
 * owner share 为 InputZone（session + input），本按钮不需要读它们——点击只切换模块级面板开关。
 *
 * 遵循官方 slot 组件约定：纯 React 组件，样式内联（不引第三方 UI 库、不引 CSS Modules，
 * 减少 client bundle 构建复杂度），文案固定中文。
 */
import { useSyncExternalStore } from 'react'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { getOpen, subscribe, toggleOpen } from './panel-store.ts'

/** 完整 props：runtime 份额 + ui-conversation 的 InputZone owner 份额。 */
export type FileButtonProps = PropsRuntime<'conversation.input.right'>

const BUTTON_STYLE: React.CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  gap: 4,
  height: 24,
  padding: '0 8px',
  border: '1px solid var(--dsw-alias-border-l2, #e2e5ea)',
  borderRadius: 6,
  background: 'var(--dsw-alias-bg-base, #fff)',
  color: 'var(--dsw-alias-label-primary, #111827)',
  fontSize: 12,
  lineHeight: 1,
  cursor: 'pointer',
  whiteSpace: 'nowrap',
}

/**
 * 文件按钮：点击切换右侧文件查看面板浮层。aria-pressed 反映当前开关态。
 */
export function FileButton(_props: FileButtonProps): React.ReactElement {
  const isOpen = useSyncExternalStore(subscribe, getOpen)
  return (
    <button
      type="button"
      title="文件查看"
      aria-label="文件查看"
      aria-pressed={isOpen}
      onClick={toggleOpen}
      style={BUTTON_STYLE}
    >
      <span aria-hidden="true">📂</span>
      <span>文件</span>
    </button>
  )
}
