/**
 * 回合产物行（`conversation.chat.turnTail` 链槽条目，2026-09 新增）。
 *
 * dsh 官方 `ui-deliverables` 在同一链槽也有一条产物行（priority 0，点击经 Host
 * openFile 用系统程序打开）。本条目以 priority -1 先尝试（链槽低 priority 先选举）：
 *   - selector 接受（本回合有写/改文件产物）→ 本行接管：点击路由到**应用内查看**；
 *   - selector 拒绝 / 抛错（无产物、ui-deliverables 缺位、契约变化）→ 自然回落官方行，
 *     官方行此时也在（链槽共享），行为退化 = 原生体验，不会丢功能。
 *
 * 点击路由（共享判定在 ../shared/turn-artifacts.ts，node --test 可测）：
 *   1. 测试报告类（占位启发式）→ 占位提示（预留未来由测试报告插件打开，docs/09）；
 *   2. 可查看文件（文本/md/code/图片白名单）→ panel-store.openPath → 本插件查看面板；
 *   3. 其余（二进制等）→ 回落 owner.openFile（Host 系统打开，与官方行同款）。
 *
 * Diff 按钮（2026-09 新增）：挂载后批量探测（POST /git/probe，一次请求全量返回），
 * 命中 changed / untracked 的产物 chip 变为分体 pill——主区开文件、右侧 Diff 开
 * 差异视图（panel-store.openDiff → iframe &mode=diff → viewer 渲染 vs HEAD）。
 * 探测失败/无仓库/git 不可用 → 不显示 Diff（静默降级，按钮默认就藏）。
 *
 * 样式（2026-09 反馈「产物区空空的」调整）：整行收进紧凑卡片容器（浅底 + 细边 +
 * 圆角 + 计数徽标 + 文件类型图标），令牌取 `var(--dsw-alias-*)`（缺失时内联兜底色，
 * 跟随主界面换肤，见 docs/08）。官方 slot 约定：纯 React + 内联样式。
 */
import { useEffect, useState } from 'react'
import type { CSSProperties } from 'react'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
// Type-only：ui-conversation 合并 GlobalStandardProps.useSessions；ui-chat 合并 turnTail 链槽键。
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
import type {} from '@deepseek-ai/dsh-client-ui-chat/client'
import { LinkIcon, classifyLinkPath } from '@deepseek-ai/dsh-client-ui-primitives'
import { basenameOf, isViewableFile, looksLikeTestReport } from '../shared/turn-artifacts.ts'
import { openDiff, openPath } from './panel-store.ts'

/** 完整 props：runtime 份额（session 域链槽）+ 链槽 selector 的 matched 份额。 */
export type ArtifactsRowProps = PropsRuntime<'conversation.chat.turnTail'> & {
  /** selector 匹配到的本回合产物路径（首见顺序去重）。 */
  matched: readonly string[]
}

/** 单行最多直出的 chip 数，超出折叠为「+N」计数（与官方 ProducedFiles 行为一致）。 */
const SHOWN_LIMIT = 6

/** 探测结论里值得显示 Diff 的状态。 */
const DIFF_SHOWABLE = new Set(['changed', 'untracked'])

// ---------- 样式（紧凑卡片，2026-09「空空的」反馈） ----------

const CARD_STYLE: CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  alignContent: 'flex-start',
  justifyContent: 'flex-start',
  flexWrap: 'wrap',
  gap: 6,
  // 防宿主拉伸三件套（2026-09 截图反馈「间距太大」）：拉伸需要 auto 高度，fit-content 锁死；
  // align-content 兜底多行分布。turnTail 外层是 column flex + gap 16，自身 margin 压到最小。
  height: 'fit-content',
  flex: '0 0 auto',
  margin: '2px 0 0',
  padding: '8px 12px',
  border: '1px solid var(--dsw-alias-border-l1, #eceff3)',
  borderRadius: 10,
  background: 'var(--dsw-alias-bg-layer-1, #f7f8fa)',
  fontSize: 12,
  lineHeight: 18,
}

const LABEL_STYLE: CSSProperties = {
  flex: 'none',
  color: 'var(--dsw-alias-label-secondary, #374151)',
  fontWeight: 600,
}

const COUNT_STYLE: CSSProperties = {
  flex: 'none',
  minWidth: 18,
  textAlign: 'center',
  padding: '0 6px',
  borderRadius: 9,
  border: '1px solid var(--dsw-alias-border-l2, #e2e5ea)',
  background: 'var(--dsw-alias-bg-base, #fff)',
  color: 'var(--dsw-alias-label-tertiary, #6b7280)',
  fontSize: 11,
  lineHeight: '16px',
}

/** 分体 pill：主区（图标+文件名，开文件）+ 右侧 Diff（开差异），探测命中才长出 Diff。 */
const PILL_STYLE: CSSProperties = {
  display: 'inline-flex',
  alignItems: 'stretch',
  maxWidth: 340,
  border: '1px solid var(--dsw-alias-border-l2, #e2e5ea)',
  borderRadius: 12,
  background: 'var(--dsw-alias-bg-base, #fff)',
  overflow: 'hidden',
}

const MAIN_STYLE: CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  gap: 5,
  minWidth: 0,
  maxWidth: 260,
  height: 24,
  padding: '0 10px',
  border: 'none',
  background: 'transparent',
  color: 'var(--dsw-alias-label-primary, #111827)',
  fontSize: 12,
  lineHeight: '18px',
  cursor: 'pointer',
  overflow: 'hidden',
  whiteSpace: 'nowrap',
  textOverflow: 'ellipsis',
}

/** 测试报告占位 chip：虚线 + 半透明，视觉上与正式路由区分。 */
const MAIN_PLACEHOLDER: CSSProperties = {
  ...MAIN_STYLE,
  borderStyle: 'dashed',
  opacity: 0.8,
}

const DIFF_STYLE: CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  height: 24,
  padding: '0 8px',
  border: 'none',
  borderLeft: '1px solid var(--dsw-alias-border-l2, #e2e5ea)',
  background: 'transparent',
  color: 'var(--dsw-alias-link, #2f5fd7)',
  fontSize: 11,
  fontWeight: 600,
  lineHeight: '18px',
  cursor: 'pointer',
}

const MORE_STYLE: CSSProperties = {
  flex: 'none',
  color: 'var(--dsw-alias-label-tertiary, #6b7280)',
}

/** 单个 chip 的主区点击路由（判定纯函数在 shared）。 */
export function routeArtifactClick(
  path: string,
  openFileHost: (path: string) => void,
): void {
  if (looksLikeTestReport(path)) {
    // 占位：未来由测试报告插件提供自己的链槽条目 / toolview 打开真正的报告视图（docs/09）。
    window.alert('【占位】测试类产物：此处预留由「测试报告插件」打开（meow-file-view 案例，见 docs/09）。')
    return
  }
  if (isViewableFile(path)) {
    openPath(path)
    return
  }
  openFileHost(path)
}

/**
 * 回合产物行：卡片容器 + label + 计数徽标 + 分体 pill chips（+ 溢出计数）。
 * @param props - 链槽 runtime 份额 + matched 产物路径。
 */
export function ArtifactsRow(props: ArtifactsRowProps): React.ReactElement {
  const openFileHost = props.openFile
  const paths = props.matched
  const shown = paths.slice(0, SHOWN_LIMIT)

  // 工作区（探测请求的树根上下文；GlobalStandardProps.useSessions 全域可用）。
  const workspace = props.useSessions((state) => {
    const current = state.current
    return current !== undefined ? state.byId[current]?.cwd : undefined
  })

  // 批量 git 探测：一次请求全量返回；失败静默 = 全体无 Diff 按钮（默认态）。
  const [probe, setProbe] = useState<Record<string, string>>({})
  useEffect(() => {
    let cancelled = false
    setProbe({})
    const body = JSON.stringify({ workspace, paths })
    fetch('/api/meow-file-view/git/probe', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body,
    })
      .then(async (res) => (res.ok ? (await res.json()) as { results?: Record<string, string> } : null))
      .then((data) => {
        if (!cancelled && data?.results !== undefined) setProbe(data.results)
      })
      .catch(() => { /* 探测失败 = 无 Diff，静默 */ })
    return () => { cancelled = true }
    // paths 内容变化（不是引用变化）才重探；workspace 切换影响 repoRoots 覆盖查找。
  }, [paths.join('�'), workspace])

  return (
    <div style={CARD_STYLE} data-meow-artifacts-row>
      <span style={LABEL_STYLE}>产物</span>
      <span style={COUNT_STYLE}>{paths.length}</span>
      {shown.map((path) => {
        const placeholder = looksLikeTestReport(path)
        const showDiff = DIFF_SHOWABLE.has(probe[path] ?? '')
        return (
          <span key={path} style={PILL_STYLE}>
            <button
              type="button"
              style={placeholder ? MAIN_PLACEHOLDER : MAIN_STYLE}
              title={placeholder
                ? `${path}（占位：测试类产物，未来由测试报告插件打开）`
                : path}
              aria-label={placeholder ? `测试类产物 ${basenameOf(path)}` : `查看 ${basenameOf(path)}`}
              onClick={() => { routeArtifactClick(path, openFileHost) }}
            >
              <LinkIcon kind={classifyLinkPath(path)} size={12} />
              {basenameOf(path)}
            </button>
            {showDiff && (
              <button
                type="button"
                style={DIFF_STYLE}
                title="查看与 git 最近提交（HEAD）的差异"
                aria-label={`Diff ${basenameOf(path)}`}
                onClick={() => { openDiff(path) }}
              >
                Diff
              </button>
            )}
          </span>
        )
      })}
      {paths.length > shown.length && (
        <span style={MORE_STYLE}>+{paths.length - shown.length}</span>
      )}
    </div>
  )
}
