/**
 * 设置页「Git 差异」节（`settings.section` list 槽，2026-09 新增）。
 *
 * 用途：产物 Diff 的 git 探测失误时的手动兜底——
 *   - gitExePath：git 可执行文件路径（默认 `git` 走 PATH；分发机没装 git 或装在
 *     非标准位置时手动指定）；
 *   - repoRoots：仓库根覆盖表（工作区树根 → repo 根；上溯探测到错误仓库 /
 *     monorepo 子目录场景手动指定）。
 * 持久化走插件自有 API（GET/POST /api/meow-file-view/git/config → 插件根
 * git-config.json），保存即生效不用重启（meow-dsh-skill-mcp 的 server.json 同款模式）。
 *
 * 结构说明：本节 **1:1 采用 meow-vision VisionModelSection 的成熟结构**
 * （flex column 根 + section 分块 + label>span+input、输入框自然高度、字符串 px 值）——
 * 该结构已在同一设置面板实机验证无样式问题；不再自创显式高度/lineHeight 等样式。
 * 另保留 height:'fit-content' 等防拉伸兜底（内联优先级高于宿主样式表，双保险）。
 * 官方 slot 约定：纯 React + 内联样式；文案简体中文硬编码（本插件无 locale 体系）。
 */
import { useEffect, useState } from 'react'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
// Type-only：加载 ui-settings 的 SlotMap 合并（'settings.section' 键 + owner 份额）。
import type {} from '@deepseek-ai/dsh-client-ui-settings/client'

/** 完整 props：runtime 份额（root 域 list 槽）+ owner 份额（close，本节用不到）。 */
export type GitSettingsProps = PropsRuntime<'settings.section'>

/** 容器通用防拉伸兜底（内联优先级高于宿主样式表；拉伸需要 auto 高度，fit-content 锁死）。 */
const FIT = {
  height: 'fit-content',
  flex: '0 0 auto',
  alignContent: 'flex-start',
  justifyContent: 'flex-start',
} as const

/** 「工作区=仓库根」行解析（每行一条；空行/# 开头注释行跳过）。 */
export function parseRepoRoots(text: string): Record<string, string> {
  const map: Record<string, string> = {}
  for (const line of text.split('\n')) {
    const trimmed = line.trim()
    if (trimmed === '' || trimmed.startsWith('#') || !trimmed.includes('=')) continue
    const eq = trimmed.indexOf('=')
    const key = trimmed.slice(0, eq).trim()
    const value = trimmed.slice(eq + 1).trim()
    if (key !== '' && value !== '') map[key] = value
  }
  return map
}

/** repoRoots 序列化回多行文本（稳定顺序，按键排序）。 */
export function formatRepoRoots(map: Record<string, string> | undefined): string {
  if (map === undefined) return ''
  return Object.keys(map).sort().map((key) => `${key}=${map[key]}`).join('\n')
}

/**
 * 「Git 差异」设置节：gitExePath 输入 + 仓库根覆盖表多行编辑 + 保存。
 * @param props - settings.section runtime 份额（本节只用到空 owner；close 忽略）。
 */
export function GitSettingsSection(_props: GitSettingsProps): React.ReactElement {
  const [gitExePath, setGitExePath] = useState('')
  const [rootsText, setRootsText] = useState('')
  const [status, setStatus] = useState<{ kind: 'idle' | 'saving' | 'ok' | 'error'; message?: string }>({ kind: 'idle' })

  useEffect(() => {
    let cancelled = false
    fetch('/api/meow-file-view/git/config')
      .then(async (res) => (res.ok ? (await res.json()) as { gitExePath?: string; repoRoots?: Record<string, string> } : null))
      .then((config) => {
        if (cancelled || config === null) return
        setGitExePath(config.gitExePath ?? '')
        setRootsText(formatRepoRoots(config.repoRoots))
      })
      .catch(() => { /* 加载失败保持空表单；保存时会再报错 */ })
    return () => { cancelled = true }
  }, [])

  const save = (): void => {
    setStatus({ kind: 'saving' })
    fetch('/api/meow-file-view/git/config', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        gitExePath: gitExePath.trim(),
        repoRoots: parseRepoRoots(rootsText),
      }),
    })
      .then(async (res) => {
        if (res.ok) { setStatus({ kind: 'ok' }); return }
        const data = (await res.json().catch(() => null)) as { error?: string } | null
        setStatus({ kind: 'error', message: data?.error ?? `保存失败（HTTP ${res.status}）` })
      })
      .catch((err: unknown) => {
        setStatus({ kind: 'error', message: err instanceof Error ? err.message : String(err) })
      })
  }

  const labelStyle = { display: 'flex', flexDirection: 'column' as const, gap: '4px' }
  const inputStyle = { padding: '6px 8px' }

  return (
    <div style={{ ...FIT, display: 'flex', flexDirection: 'column', gap: '14px', maxWidth: '560px' }}>
      <section style={{ ...FIT, display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <h3 style={{ margin: 0, fontSize: '15px' }}>Git 差异（产物 Diff）</h3>
        <p style={{ margin: 0 }}>
          产物 Diff 依赖本地 git（两段式自动探测：目录上溯找 <code>.git</code> → git 命令可用性）。
          探测不到或探测失误时，可在此手动指定；保存即生效，无需重启。
        </p>
        <label style={labelStyle}>
          <span>git 可执行文件路径（留空 = git 走 PATH）</span>
          <input
            value={gitExePath}
            placeholder="例如 D:\Program Files\Git\cmd\git.exe"
            onChange={(event) => { setGitExePath(event.target.value) }}
            style={inputStyle}
          />
        </label>
        <label style={labelStyle}>
          <span>仓库根覆盖（每行一条：工作区路径=仓库根路径；# 开头为注释）</span>
          <textarea
            rows={3}
            value={rootsText}
            placeholder={'E:\\workspace\\my-project=E:\\workspace\\my-project\\sub\\repo\nE:\\monorepo=E:\\monorepo\\packages\\app'}
            onChange={(event) => { setRootsText(event.target.value) }}
            style={{ ...inputStyle, resize: 'vertical' }}
          />
        </label>
        <div style={{ ...FIT, display: 'flex', alignItems: 'center', gap: '10px' }}>
          <button
            type="button"
            disabled={status.kind === 'saving'}
            onClick={save}
            style={{ padding: '6px 14px' }}
          >
            {status.kind === 'saving' ? '保存中…' : '保存'}
          </button>
          {status.kind === 'ok' && <span>已保存 ✓</span>}
          {status.kind === 'error' && <span>{status.message}</span>}
        </div>
      </section>
    </div>
  )
}
