/**
 * 右侧文件查看面板浮层（shell.overlay 槽）。
 *
 * 与 meow-dsh-task 的 TaskPanel 同款：ui-layout 的 `shell.overlay` 是加性全屏浮层
 * （root 域，列表槽），渲染层 `.overlayLayer` 默认 click-through（pointer-events: none），
 * 条目根节点由 CSS 恢复 pointer-events: auto。
 *
 * 本组件：全屏遮罩 + 右停靠 80% 宽面板 + `<iframe src="/meow-file-view?workspace=…">`。
 * iframe 加载的是 node 半查看器页面，数据经同源 `/api/meow-file-view/*` fetch，
 * 浏览器半零本地文件读取。背景点击关闭面板，面板内部点击不冒泡。
 *
 * 懒挂载 + 保持挂载（与 TaskPanel 的"关闭即卸载"不同）：
 *   - 首次打开前不渲染（不预加载 3MB 查看器页）；
 *   - 打开过一次后始终渲染，关闭时仅 `display: none` 隐藏而不卸载 —— iframe 内的
 *     目录树展开/折叠状态、选中的文件、预览内容全部保留，再次打开不再重新加载、无需重找文件。
 *   - 工作区跟随：root 域 slot 用全局标准座 `useSessions` 读当前活动会话的
 *     `SessionSummary.cwd`，经 `encodeURIComponent` 注入 iframe URL 的 `?workspace=`；
 *     工作区切换 → 选择器变化 → 本组件重渲染 → iframe 以新 workspace 重载。
 *     无当前会话时回落 `/meow-file-view`（/api 走默认工作区兜底）。
 */
import { useEffect, useSyncExternalStore, useState } from 'react'
import type { CSSProperties } from 'react'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { relWithinRoot } from '../shared/turn-artifacts.ts'
import { getOpen, getRequestedMode, getRequestedPath, setOpen, subscribe } from './panel-store.ts'

/** 完整 props：runtime 份额（root 域，无 owner 份额）。 */
export type FilePanelProps = PropsRuntime<'shell.overlay'>

const OVERLAY_STYLE: CSSProperties = {
  position: 'absolute',
  inset: 0,
  zIndex: 30,
  background: 'rgba(15, 23, 42, 0.35)',
}

const PANEL_STYLE: CSSProperties = {
  position: 'absolute',
  top: 0,
  right: 0,
  bottom: 0,
  // 93% 宽 + 不设上限（2026-09 反馈：文档阅读区尽量大，宽屏不设 1100px 帽子）
  width: '93%',
  maxWidth: 'none',
  display: 'flex',
  flexDirection: 'column',
  background: 'var(--dsw-alias-bg-base, #fff)',
  borderLeft: '1px solid var(--dsw-alias-border-l2, #e2e5ea)',
  boxShadow: '-8px 0 24px rgba(0, 0, 0, 0.18)',
}

const HEADER_STYLE: CSSProperties = {
  flex: 'none',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  gap: 8,
  height: 44,
  padding: '0 12px 0 16px',
  borderBottom: '1px solid var(--dsw-alias-border-l1, #eceff3)',
  fontSize: 14,
  fontWeight: 600,
  color: 'var(--dsw-alias-label-primary, #111827)',
}

const CLOSE_STYLE: CSSProperties = {
  width: 28,
  height: 28,
  border: 'none',
  borderRadius: 6,
  background: 'transparent',
  color: 'var(--dsw-alias-label-tertiary, #6b7280)',
  fontSize: 18,
  lineHeight: 1,
  cursor: 'pointer',
}

const IFRAME_STYLE: CSSProperties = {
  flex: 1,
  width: '100%',
  height: '100%',
  border: 0,
}

/**
 * 右侧文件查看面板浮层：首次打开前不渲染；打开过一次后始终渲染，
 * 关闭时用 display:none 隐藏（iframe 与树状态保留），打开直接复用。
 */
export function FilePanel(props: FilePanelProps): React.ReactElement | null {
  const isOpen = useSyncExternalStore(subscribe, getOpen)
  // 懒挂载：首次打开才加载 iframe；everOpened 置位后永不卸载（保持树/预览状态）。
  const [everOpened, setEverOpened] = useState(false)
  useEffect(() => {
    if (isOpen) setEverOpened(true)
  }, [isOpen])

  // 当前活动会话的工作区路径（SessionSummary.cwd，全局标准座 useSessions）。
  // 选择器订阅：会话/工作区切换时本组件重渲染，iframe 以新 workspace 重载。
  const workspace = props.useSessions((state) => {
    const current = state.current
    return current !== undefined ? state.byId[current]?.cwd : undefined
  })

  // 产物联动（chat 回合产物 chips → openPath/openDiff）：把请求路径换算成树根内 rel
  // 注入 `?path=`，viewer.js 初始化时直达该文件；Diff 请求再注入 `&mode=diff`。
  // 树根外/无工作区时传原始路径 —— 查看器会给出明确的加载失败（比静默忽略更可诊断）。
  // path/mode 只在 iframe（重）加载时生效，src 不变就不重载，「状态保留」不受影响。
  const requestedPath = useSyncExternalStore(subscribe, getRequestedPath)
  const requestedMode = useSyncExternalStore(subscribe, getRequestedMode)
  const pathParam = requestedPath !== null
    ? (workspace !== undefined ? relWithinRoot(workspace, requestedPath) : null) ?? requestedPath
    : null
  const frameSrc = workspace
    ? `/meow-file-view?workspace=${encodeURIComponent(workspace)}`
    : '/meow-file-view'
  const fullSrc = pathParam !== null
    ? `${frameSrc}&path=${encodeURIComponent(pathParam)}${requestedMode === 'diff' ? '&mode=diff' : ''}`
    : frameSrc

  // 从未打开过 → 不渲染（避免预加载 3MB 查看器页）
  if (!everOpened) return null
  // 打开过 → 始终渲染；关闭时仅隐藏 overlay，iframe 保持挂载、状态保留
  const overlayStyle: CSSProperties = isOpen ? OVERLAY_STYLE : { ...OVERLAY_STYLE, display: 'none' }
  return (
    <div style={overlayStyle} onClick={() => setOpen(false)}>
      <div style={PANEL_STYLE} onClick={(event) => event.stopPropagation()}>
        <div style={HEADER_STYLE}>
          <span>文件查看</span>
          <button
            type="button"
            aria-label="关闭文件查看面板"
            title="关闭"
            onClick={() => setOpen(false)}
            style={CLOSE_STYLE}
          >
            ×
          </button>
        </div>
        <iframe src={fullSrc} title="文件查看" style={IFRAME_STYLE} />
      </div>
    </div>
  )
}
