/**
 * meow-file-view 浏览器半（browser half）入口。
 *
 * 双面插件包：node 半负责 Web 路由（/meow-file-view 页 + /api/meow-file-view JSON API）；
 * 本 browser 半用 dsh 的 slot 系统向 dsh web SPA 注入 UI：
 *   1. `conversation.input.right` —— 输入框右端「文件」按钮（空置槽，发送键前）；
 *   2. `shell.overlay`            —— 右侧文件查看面板浮层（root 域加性浮层），iframe 嵌 /meow-file-view；
 *   3. `conversation.chat.turnTail` —— 回合产物行（链槽条目，priority -1 先于官方
 *      ui-deliverables 行选举）：文件类产物点击 → 应用内查看面板（?path= 直达）；
 *      命中 git 探测的产物长出 Diff 按钮 → 差异视图（&mode=diff，vs HEAD）；
 *      测试报告类 → 占位提示（预留未来由测试报告插件打开，见 docs/09）。
 *   4. `settings.section` —— 设置页「Git 差异」节：git 路径 / 仓库根覆盖手动兜底。
 *
 * 构建：`tsdown.config.ts` 用 dsh 的 clientBundle 结构产出 `lib/client.js`
 * （浏览器 CJS + `window.__ModuleLoader__.load({ id: 'meow-file-view', factory })`）。
 * 浏览器半不读本地文件，全部数据经 node 半 `/api/meow-file-view/*` 同源 fetch。
 *
 * 注意（类型面）：本文件对 `@deepseek-ai/*` 全部为 type-only import（含 SlotMap 合并），
 * 运行时零跨插件值导入 → 通过 client bundle 纯度门禁。
 */
import type { Context as ClientContext } from '@deepseek-ai/cordis'
// Type-only：加载 ui-renderer 对 cordis Context 的 `slots` 服务增强
// （2026-09 起 dsh 删除 client/runtime，类型宿主迁移后的等价导入）。
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client'
// Type-only：加载 ui-conversation / ui-layout / ui-chat 的 SlotMap 合并，
// 使 `conversation.input.right` / `shell.overlay` / `conversation.chat.turnTail` 成为已声明的 slot 键。
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
import type {} from '@deepseek-ai/dsh-client-ui-layout/client'
import type {} from '@deepseek-ai/dsh-client-ui-chat/client'
import type {} from '@deepseek-ai/dsh-client-ui-settings/client'
import { ArtifactsRow } from './ArtifactsRow.tsx'
import { FileButton } from './FileButton.tsx'
import { FilePanel } from './FilePanel.tsx'
import { GitSettingsSection } from './GitSettings.tsx'
import { selectTurnArtifacts } from '../shared/turn-artifacts.ts'

export { ArtifactsRow } from './ArtifactsRow.tsx'
export { FileButton } from './FileButton.tsx'
export { FilePanel } from './FilePanel.tsx'
export { GitSettingsSection } from './GitSettings.tsx'
export type { FileButtonProps } from './FileButton.tsx'
export type { FilePanelProps } from './FilePanel.tsx'

/** 插件名（cordis 诊断标签；loader 条目名仍为包名 meow-file-view）。 */
export const name = 'meow-file-view-client'

/** 需要的服务：`slots`（SlotRegistry，由 @deepseek-ai/dsh-client-runtime 提供）。 */
export const inject = ['slots']

/**
 * 客户端插件体：注册输入框按钮 + 右侧浮层（slot 注入，随插件卸载自动回收）。
 * @param ctx - 客户端根上下文（含 ctx.slots / ctx.effect 等 cordis 核心面）。
 */
export function apply(ctx: ClientContext): void {
  ctx.slots.inject('conversation.input.right', () => ctx.slots.register({
    name: 'conversation.input.right',
    id: 'meow-file-view',
    order: 30, // 「任务」按钮 order 20 之后，两按钮并排
  }, FileButton))

  ctx.slots.inject('shell.overlay', () => ctx.slots.register({
    name: 'shell.overlay',
    id: 'meow-file-view-panel',
  }, FilePanel))

  // 回合产物行：链槽（selector 路由，多条目共存、先到先选举）。官方 ui-deliverables
  // 产物行 priority 0；本条目 -1 先尝试 —— 接受（本回合有产物）即接管为「应用内查看」，
  // 拒绝/异常（无产物、ui-deliverables 缺位、契约变化）自然回落官方行，行为退化 = 原生。
  ctx.slots.inject('conversation.chat.turnTail', () => ctx.slots.register({
    name: 'conversation.chat.turnTail',
    // chain 槽无 id（那是 list 槽字段）；诊断标签靠 registrant（Service 包装自动标注调用方）。
    priority: -1,
    select: selectTurnArtifacts,
  }, ArtifactsRow))

  // 设置页「Git 差异」节：order 18（meow-dsh-skill-mcp 的 MCP 16.5 之后、agent 预设 20 之前）。
  ctx.slots.inject('settings.section', () => ctx.slots.register({
    name: 'settings.section',
    id: 'meow-file-view-git',
    order: 18,
    label: 'Git 差异',
  }, GitSettingsSection))
}
