/**
 * meow-file-view 浏览器半 —— 文件查看面板开关的共享状态（模块级 store）。
 *
 * 输入框按钮（conversation.input.right，session 域）与右侧浮层
 * （shell.overlay，root 域）挂在**不同的 slot 作用域**上，但需要共享同一个
 * 「面板打开/关闭」状态。这里用模块级发布订阅 + React `useSyncExternalStore`
 * 桥接（不依赖 cordis store，跨 slot 域天然共享；插件卸载即随 bundle 释放）。
 *
 * 这是浏览器半的内部实现细节，不参与任何跨插件值导入（无 @deepseek-ai 运行时依赖）。
 */

type Listener = () => void

let open = false
const listeners = new Set<Listener>()

/**
 * 产物联动请求：chat 回合产物 chips 点击时带的目标路径（原始工具参数路径，
 * 未必相对树根）。FilePanel 组 iframe URL 时把树根内的换算成 rel 注入 `?path=`。
 *
 * 只增不清：path 参数只在 iframe（重）加载时被 viewer.js 读一次，之后留存
 * 不影响已挂载 iframe（src 不变就不重载）；新请求 = 新 src = 重载直达目标文件。
 */
let requestedPath: string | null = null

/**
 * 打开形态：'view' 普通文件视图；'diff' 差异视图（vs HEAD，viewer.js 按 ?mode= 进入）。
 * 随 requestedPath 一起更新（src 变化 → iframe 重载 → viewer 按 mode 渲染）。
 */
let requestedMode: 'view' | 'diff' = 'view'

/** 订阅开关变化；返回退订函数（React useSyncExternalStore 契约）。 */
export function subscribe(fn: Listener): () => void {
  listeners.add(fn)
  return () => {
    listeners.delete(fn)
  }
}

/** 当前开关状态快照（布尔值，引用稳定，可直接作为 useSyncExternalStore 的 getSnapshot）。 */
export function getOpen(): boolean {
  return open
}

/** 打开/关闭面板；无变化时 no-op（避免无谓重渲染）。 */
export function setOpen(next: boolean): void {
  if (open === next) return
  open = next
  for (const fn of [...listeners]) fn()
}

/** 切换面板开关。 */
export function toggleOpen(): void {
  setOpen(!open)
}

/** 当前产物联动请求路径（null = 无，普通打开）。 */
export function getRequestedPath(): string | null {
  return requestedPath
}

/** 产物 chips 点击入口：记下目标路径并打开面板（iframe 以新 src 重载直达该文件）。 */
export function openPath(path: string): void {
  requestedPath = path
  requestedMode = 'view'
  setOpen(true)
}

/** 当前请求形态。 */
export function getRequestedMode(): 'view' | 'diff' {
  return requestedMode
}

/** Diff 按钮点击入口：openPath(path, 'diff')。 */
export function openDiff(path: string): void {
  requestedPath = path
  requestedMode = 'diff'
  setOpen(true)
}
